package com.example.starter.api;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import com.example.starter.domain.WorkType;

/**
 * 写操作请求 DTO。所有写操作携带 requestId 作为幂等键，
 * 指纹覆盖 requestId 与全部业务字段。
 */
public final class Requests {

    private Requests() {
    }

    /** 路段建档请求。 */
    public record SegmentRegisterRequest(
            @NotBlank String requestId,
            @NotBlank String code,
            @NotBlank String name) {
    }

    /** 树木建档请求，评估因子用于合成评估模型。 */
    public record TreeRegisterRequest(
            @NotBlank String requestId,
            @NotBlank String segmentCode,
            @NotBlank String treeCode,
            @DecimalMin("0") double tiltDegrees,
            @Min(0) @Max(3) int diseaseLevel,
            @Min(0) int ageYears,
            @Min(0) @Max(3) int windExposure) {
    }

    /** 作业许可申请请求。 */
    public record PermitApplyRequest(
            @NotBlank String requestId,
            @NotBlank String segmentCode,
            @NotNull Long planId,
            @NotNull WorkType workType) {
    }

    /** 作业回传请求，前后照片标识与弃枝清运记录必填。 */
    public record ReportSubmitRequest(
            @NotBlank String requestId,
            @NotBlank String permitNo,
            @NotBlank String beforePhoto,
            @NotBlank String afterPhoto,
            @NotBlank String disposalRecord) {
    }

    /** 大风预警发布请求，level 为合成预警级别1-4。 */
    public record WarningPublishRequest(
            @NotBlank String requestId,
            @NotBlank String warningNo,
            @Min(1) @Max(4) int level) {
    }

    /** 大风预警解除请求。 */
    public record WarningCancelRequest(
            @NotBlank String requestId,
            @NotBlank String warningNo) {
    }

    /** 年度风险复评请求，携带最新评估因子。 */
    public record ReevaluateRequest(
            @NotBlank String requestId,
            @NotBlank String treeCode,
            @DecimalMin("0") double tiltDegrees,
            @Min(0) @Max(3) int diseaseLevel,
            @Min(0) int ageYears,
            @Min(0) @Max(3) int windExposure) {
    }
}

package com.example.starter.api;

import java.time.LocalDateTime;
import java.util.List;

/**
 * 响应 DTO。可空字段为 null 时表示该业务对象未产生（如非一级风险不生成修剪计划）。
 */
public final class Responses {

    private Responses() {
    }

    /** 路段建档响应。 */
    public record SegmentResponse(long id, String code, String name) {
    }

    /** 树木建档响应，planId/deadline 仅一级风险时非空。 */
    public record TreeRegisterResponse(long treeId, String treeCode, String segmentCode,
                                       double riskScore, int riskLevel,
                                       Long planId, LocalDateTime deadline) {
    }

    /** 作业许可响应，deadline 为签发时既定时限。 */
    public record PermitResponse(String permitNo, String status, LocalDateTime deadline) {
    }

    /** 作业回传响应，onTime 表示是否按期闭环（恰第7日闭环为按期）。 */
    public record ReportResponse(long reportId, String permitNo, long planId, boolean onTime) {
    }

    /** 预警发布响应，frozenSegments 为本次冻结的高风险路段编码。 */
    public record WarningResponse(String warningNo, int level, List<String> frozenSegments) {
    }

    /** 预警解除响应，liftedSegments 为解除冻结的路段编码。 */
    public record WarningCancelResponse(String warningNo, List<String> liftedSegments) {
    }

    /** 年度复评响应，rescheduled 表示评级变化触发了计划重排。 */
    public record ReevaluateResponse(String treeCode, int oldLevel, int newLevel,
                                     boolean rescheduled, Long newPlanId,
                                     LocalDateTime newDeadline) {
    }

    /**
     * 台账行：各路段风险分布与修剪闭环率。closureRate=闭环数/(待修剪+已闭环+已督办)，
     * 重排计划不计入分母；无计划时为 null。
     */
    public record LedgerEntry(String segmentCode,
                              long level1Count, long level2Count, long level3Count, long level4Count,
                              long totalPlans, long closedPlans, long escalatedPlans,
                              Double closureRate) {
    }

    /** 统一错误响应。 */
    public record ErrorResponse(String code, String message) {
    }
}

package com.example.starter.service;

/**
 * 业务异常：携带 HTTP 状态码与稳定错误码，由全局异常处理器输出统一错误响应。
 */
public class BusinessException extends RuntimeException {

    private final int status;
    private final String code;

    public BusinessException(int status, String code, String message) {
        super(message);
        this.status = status;
        this.code = code;
    }

    public int status() {
        return status;
    }

    public String code() {
        return code;
    }
}

package com.example.starter.service;

/**
 * 服务调用结果：HTTP 状态码与响应体，幂等命中时原样回放首次结果。
 */
public record ServiceResult(int status, Object body) {
}

package com.example.starter.service;

/**
 * 合成风险评估模型（确定性、可复算）：
 * 得分 = 倾斜角*1.2 + 病害等级*15 + min(树龄,60)*0.5 + 风口暴露等级*8；
 * 一级(最高风险) >= 70，二级 >= 45，三级 >= 25，其余为四级。
 */
public final class RiskModel {

    public static final int LEVEL_1_THRESHOLD = 70;
    public static final int LEVEL_2_THRESHOLD = 45;
    public static final int LEVEL_3_THRESHOLD = 25;

    private RiskModel() {
    }

    public static double score(double tiltDegrees, int diseaseLevel, int ageYears, int windExposure) {
        return tiltDegrees * 1.2 + diseaseLevel * 15.0
                + Math.min(ageYears, 60) * 0.5 + windExposure * 8.0;
    }

    public static int level(double score) {
        if (score >= LEVEL_1_THRESHOLD) {
            return 1;
        }
        if (score >= LEVEL_2_THRESHOLD) {
            return 2;
        }
        if (score >= LEVEL_3_THRESHOLD) {
            return 3;
        }
        return 4;
    }
}

